        let mut msg = Self::default();
        let mut reader = PbReader::new(bytes);
        while let Some(field) = reader.next()? {
            match field.number {
                1 => {
                    msg.batch = None;
                    msg.group_error = None;
                    msg.assignment = Some(Box::new(Assignment::decode(&field.bytes_value)?));
                }
                2 => {
                    msg.assignment = None;
                    msg.group_error = None;
                    msg.batch = Some(Box::new(RecordBatch::decode(&field.bytes_value)?));
                }
                3 => {
                    msg.assignment = None;
                    msg.batch = None;
                    msg.group_error = Some(Box::new(GroupError::decode(&field.bytes_value)?));
                }
                _ => {
                    msg.unknown_fields.extend_from_slice(&field.raw_value);
                }
            }
        }
        Ok(msg)
